<section class="auth-wrap"><div class="auth-aside"><span class="eyebrow">Your catering plans</span><h1>Start with an account.</h1><p>Keep reservations, event details, payment updates, and notifications connected to you.</p></div><form class="auth-form" method="post" action="<?= rc_e(rc_endpoint()) ?>" autocomplete="on"><?= rc_csrf_field() ?><input type="hidden" name="action" value="register"><h2>Create customer account</h2><p class="muted">All fields are required unless marked optional.</p><div class="field"><label for="full-name">Full name</label><input id="full-name" name="full_name" maxlength="120" autocomplete="name" required></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" maxlength="254" autocomplete="email" required></div><div class="field"><label for="phone">Mobile number</label><input id="phone" name="contact_number" type="tel" maxlength="30" autocomplete="tel" required></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" minlength="10" autocomplete="new-password" required><small>Use at least 10 characters.</small></div><button class="button form-submit" type="submit">Create account</button><p class="muted">Already registered? <a class="text-link" href="<?= rc_url('login') ?>">Sign in</a></p></form></section>
